function financialRows(series:DashboardMetricSeries,granularity:WidgetConfig["granularity"]){const daily=new Map<string,{date:string;revenue:number;spend:number}>();for(const point of series.gross_revenue??[])daily.set(point.date,{date:point.date,revenue:point.value,spend:0});for(const point of series.meta_spend??[]){const row=daily.get(point.date)??{date:point.date,revenue:0,spend:0};row.spend=point.value;daily.set(point.date,row)}const grouped=new Map<string,{date:string;revenue:number;spend:number}>();for(const row of [...daily.values()].sort((a,b)=>a.date.localeCompare(b.date))){const date=new Date(`${row.date}T00:00:00Z`);let key=row.date;if(granularity==="monthly")key=`${row.date.slice(0,7)}-01`;else if(granularity==="weekly"){const weekday=(date.getUTCDay()+6)%7;key=shiftCalendarDate(row.date,-weekday)}const group=grouped.get(key)??{date:key,revenue:0,spend:0};group.revenue+=row.revenue;group.spend+=row.spend;grouped.set(key,group)}return [...grouped.values()].map(row=>({...row,roas:row.spend>0?row.revenue/row.spend:null,label:new Intl.DateTimeFormat("pt-BR",{timeZone:"UTC",...(granularity==="monthly"?{month:"short",year:"2-digit"} as const:{day:"2-digit",month:"short"} as const)}).format(new Date(`${row.date}T00:00:00Z`))}))}

